function CONSISTENCY_COUNT(evolve, n):
    count <- 0
    for x in 0 .. n-1:
        if evolve(x) == x:
            count <- count + 1
    return count

function SELF_CONSISTENT(evolve, n):
    return CONSISTENCY_COUNT(evolve, n) > 0

