from typing import Callable

def consistency_count(evolve: Callable[[int], int], n: int) -> int:
    return sum(1 for x in range(n) if evolve(x) == x)

def self_consistent(evolve: Callable[[int], int], n: int) -> bool:
    return consistency_count(evolve, n) > 0

