function ORBIT_CYCLE_LEN(evolve, seed):
    seen <- empty map ; path <- empty list ; x <- seed
    while x not in seen:
        seen[x] <- length(path) ; append x to path ; x <- evolve(x)
    return length(path) - seen[x]        # length of the cycle

function LEAST_CONSISTENT_POWER(evolve, n):
    best <- +infinity
    for seed in 0 .. n-1:
        best <- min(best, ORBIT_CYCLE_LEN(evolve, seed))
    return best

