from typing import Callable, Dict, List

def orbit_cycle_len(evolve: Callable[[int], int], seed: int) -> int:
    seen: Dict[int, int] = {}
    path: List[int] = []
    x = seed
    while x not in seen:
        seen[x] = len(path)
        path.append(x)
        x = evolve(x)
    return len(path) - seen[x]

def least_consistent_power(evolve: Callable[[int], int], n: int) -> int:
    return min(orbit_cycle_len(evolve, s) for s in range(n))
